def roman_to_int(s):
    roman = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev_value = 0
    for char in reversed(s):
        value = roman[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total

def flatten(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def rotate_matrix(m):
    if not m:
        return []
    n = len(m)
    return [[m[n - j - 1][i] for j in range(n)] for i in range(n)]

def group_anagrams(words):
    from collections import defaultdict

    groups = defaultdict(list)
    for word in words:
        sorted_word = ''.join(sorted(word))
        groups[sorted_word].append(word)

    result = []
    for key in sorted(groups.keys()):
        result.append(sorted(groups[key]))

    return result

def longest_common_prefix(strs):
    if not strs:
        return ""
    shortest = min(strs, key=len)
    for i, char in enumerate(shortest):
        for word in strs:
            if word[i] != char:
                return shortest[:i]
    return shortest

def is_valid_ipv4(s):
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == '0':
            return False
        if not 0 <= int(part) <= 255:
            return False
    return True

def median(nums):
    """Return the median of a non-empty list of numbers."""
    s = sorted(nums)
    mid = len(s) // 2
    if len(s) % 2 == 0:
        return (s[mid - 1] + s[mid]) / 2
    else:
        return s[mid]

def chunk(items, size):
    """Split items into lists of length size. The last list may be shorter."""
    return [items[i:i + size] for i in range(0, len(items), size)]

def is_sorted(nums, reverse=False):
    """True if nums is sorted ascending (or descending if reverse=True).
    Equal neighbours are allowed."""
    for a, b in zip(nums, nums[1:]):
        if reverse:
            if a < b:
                return False
        else:
            if a > b:
                return False
    return True

def fib(n):
    """Return the n-th Fibonacci number, with fib(0) = 0 and fib(1) = 1."""
    if n < 2:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def average(nums):
    """Return the mean of a list of numbers, ignoring None values. Returns None for empty lists or lists with only None."""
    filtered = [num for num in nums if num is not None]
    if not filtered:
        return None
    return round(sum(filtered) / len(filtered), 2)
